import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { choiceDeltaSchema, type ChoiceDelta } from "./choice-delta.js";
import { finishReason1Schema, type FinishReason1 } from "./unions/finish-reason1.js";
import { logprobsSchema, type Logprobs } from "./unions/logprobs.js";

export type Choice = {
  /** A chat completion delta generated by streamed model responses. */
  delta: ChoiceDelta;
  finishReason?: FinishReason1;
  index: number;
  logprobs?: Logprobs;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const choiceSchema: Schema<Choice> = s.object<Choice>(
  {
    delta: choiceDeltaSchema,
    finishReason: s.optional(s.lazy(() => finishReason1Schema)),
    index: s.int(),
    logprobs: s.optional(s.lazy(() => logprobsSchema)),
    _keysMap: {
      finishReason: "finish_reason",
    },
  },
  { additionalProperties: s.json() },
);
